<template>
	<div class="home">
		<button v-on:click="connect">连接设备</button>
		<!-- <button v-on:click="set">Set</button> -->
		<!-- <button v-on:click="clear">Clear</button> -->
		<button v-on:click="disconnect">断开连接</button>
		<!-- <button v-on:click="upload">Upload</button> -->
		<button v-on:click="upload" v-if="chipData">上传数据</button>
		<div class="key-id">{{ chip && chip.id }}</div>
		<pre v-html="chipDataHtml"></pre>

		<!-- <div class="loader">1</div> -->
		<!-- <div>
			{{ chipData }}
		</div> -->
	</div>
</template>

<script lang="ts">
import Vue from 'vue'
import ChipReaderWatcher from '../utils/chipReaderWatcher'
import { ChipReader } from '../utils/chipReader'
import { Chip } from '../utils/chips'
import { DataChip } from '../utils/dataChip'
import { ChipObject, DataChipObject } from '../utils/chipLib'
import SyntaxHighlight from './../common/syntax'
import { SET_2 } from './../common/test'
import axios from 'axios'

// axios.defaults.baseURL = process.env.NODE_ENV == 'development' ? '/' : window.server //默认接口地址

export default Vue.extend({
	name: 'HomeView',
	data() {
		return {
			chipReaderWatcher: ChipReaderWatcher,
			chipReader: null as ChipReader | null,
			chip: null as Chip | null,
			chipData: null as ChipObject | null,
			cdata: { data: {} },
		}
	},
	async created() {
		this.chipReaderWatcher.onConnect(this.chipReaderConnected)

		// await this.$request('/edian/product/queryIndexContent?isnToLoginPage=true', 'GET').then((data: any) => {})
	},
	methods: {
		async connect() {
			try {
				await this.chipReaderWatcher.start()
			} catch (error) {
				console.log(error)
			}
		},
		async disconnect() {
			try {
				await this.chipReaderWatcher.stop()
			} catch (error) {
				// console.error(error.message)
			}
		},
		upload() {
			var machineData = null
			if (this.chipData !== null) {
				if ('chipMachineData' in this.chipData) {
					machineData = this.chipData.chipMachineData
				}
			}
			console.log(machineData)
			axios
				.post('https://mdcdev.kxunpt.cn/api/keiser/add', {
					business: 'sxkx',
					equipment_id: '62',
					data: JSON.stringify(machineData),
				})
				.then(res => {
					console.log(res.data.code)
					if (res.data.code == 0) {
						alert(res.data.message)
					} else {
						alert(res.data.message)
					}
				})
			// $ajax.ajax({
			// 	type: 'post',
			// 	url: 'http://mdcdev.kxunpt.cn/api/keiser/add',
			// 	data: JSON.stringify({
			// 		address: 'luoyang',
			// 		hobbies: 'dance',
			// 	}),
			// 	dataType: 'json',
			// })
		},
		chipReaderConnected(chipReader: ChipReader) {
			this.chipReader = chipReader
			this.chipReader.onDisconnect(this.chipReaderDisconnected)
			this.chipReader.onChipDetect(this.chipDetected)
		},
		chipReaderDisconnected() {
			this.chipReader = null
		},
		async chipDetected(chip: Chip) {
			this.chip = chip
			this.chip.onDisconnect(this.chipDisconnected)
			this.chip.onData((data: ChipObject) => (this.chipData = data))
		},
		chipDisconnected() {
			this.chip = null
			this.chipData = null
		},
		async set() {
			console.log('set')
			if (this.chip instanceof DataChip) {
				this.chipData = null
				try {
					console.log(SET_2)
					await this.chip.setData(SET_2)
				} catch (error) {
					// console.error(error.message)
				}
			}
		},
		async clear() {
			if (this.chip instanceof DataChip) {
				this.chipData = null
				try {
					await this.chip.clearData()
				} catch (error) {
					// console.error(error.message)
				}
			}
		},
	},

	watch: {
		chipData: {
			handler: function (val) {
				console.log(val)
			},
			deep: true,
		},
		chip: {
			handler: function (val) {},
			deep: true,
		},
	},

	computed: {
		chipDataHtml: function (): string {
			if (!(this.chipData instanceof DataChipObject) || !this.chipData.validStructure) {
				return ''
			}
			console.log(this.chipData)
			return SyntaxHighlight(this.chipData.machineData)
		},
	},
})
</script>
